X27.dspNew=function(){ if(!NEED()) return; XA.fm('Log a dispute — which customer?',[{k:'c',label:'Customer *',type:'select',opts:[['','— choose —']].concat(custOpts())}],o=>{ if(!o.c){ toast('Choose the customer.',true); return false; } setTimeout(()=>{ const L=invList(o.c); if(!L.length){ toast('This customer has no invoices.',true); return; } XA.fm('Dispute — '+cn(o.c),[{k:'inv',label:'Invoice *',type:'select',opts:L.map(i=>[i.no,i.no+' · '+dmy(i.date)+' · AED '+M(i.amt)])},{k:'amt',label:'Disputed amount (AED, blank = whole invoice)',type:'number',half:1},{k:'promised',label:'Promise to resolve by',type:'date',val:addDays(today(),7),half:1},{k:'reason',label:'Customer’s reason *',type:'textarea',rows:2,ph:'e.g. says counter reading was wrong / machine was down'}],p=>{ if(!p.reason.trim()){ toast('Write the reason.',true); return false; } if(DS().some(d=>dOpen(d)&&d.inv===p.inv)){ toast('This invoice already has an open dispute.',true); return false; } const inv=L.find(i=>i.no===p.inv); const d={id:uid(),inv:p.inv,cid:o.c,amount:num(p.amt)||inv.amt,reason:p.reason.trim(),promised:p.promised,opened:today(),by:who(),status:'Open',note:'',resolved:''}; DS().push(d); audit('opened','Dispute',d.inv+' · '+cn(d.cid)); XA.save(); toast('Dispute logged — invoice is on hold from reminders.'); }); },60); }); };
